# Characterisation (golden) tests: record legacy output, then check a refactor against it
def legacy_price(qty, member):
    p = qty * 10
    if qty > 5:
        p = p - p * 10 / 100
    if member:
        p = p - 2
    return round(p, 2)

def refactored_price(qty, member):
    base = qty * 10
    discount = 0.9 if qty > 5 else 1.0
    return round(base * discount - (2 if member else 0), 2)

def refactored_wrong(qty, member):
    base = qty * 10
    discount = 0.9 if qty >= 5 else 1.0     # boundary slip
    return round(base * discount - (2 if member else 0), 2)

inputs = [(q, m) for q in (0, 1, 5, 6, 20) for m in (False, True)]
golden = {i: legacy_price(*i) for i in inputs}   # recorded once from old code
print("recorded", len(golden), "golden cases")

for name, fn in (("refactored", refactored_price), ("refactored_wrong", refactored_wrong)):
    diffs = [(i, golden[i], fn(*i)) for i in inputs if fn(*i) != golden[i]]
    print(name, "OK" if not diffs else "DIFFERS: " + str(diffs))
